import{_ as t,o as e,c as a,ag as _}from"./chunks/framework.DaAXJYxM.js";const l=JSON.parse('{"title":"第49章 一件一件","description":"","frontmatter":{},"headers":[],"relativePath":"第49章_一件一件.md","filePath":"第49章_一件一件.md"}'),o={name:"第49章_一件一件.md"};function r(n,p,s,c,i,u){return e(),a("div",null,[...p[0]||(p[0]=[_('<h1 id="第49章-一件一件" tabindex="-1">第49章 一件一件 <a class="header-anchor" href="#第49章-一件一件" aria-label="Permalink to &quot;第49章 一件一件&quot;">​</a></h1><p>她回来以后的第一件事，不是谈我们，是给我一张单子。</p><p>单子是她手写的，拍照发过来。上面是六行，每行一个名字，一个数量，后面跟着一个城市。字很小，写得很挤，一看就是拿一张纸的背面写的。</p><p>她说，这个你先帮我发。</p><p>我说，发去哪儿。</p><p>她说，发给人。</p><p>我说，什么人。</p><p>她说，跟我一起拼团的那几个。</p><p>她说，我把话说清楚了。那个卖家跑了，我垫的钱。我不打算自己扛，我打算一家一家退给她们，退完我去挂，挂到有人接。</p><p>我说，你那边不是要开学了。</p><p>她说，所以要快。</p><p>她说，我现在过不去，我只能你帮我发。</p><p>我看完这一段，坐在那儿想了一会儿。</p><p>我说，我没发过。</p><p>她说，我知道。</p><p>我说，那我怎么发。</p><p>她说，你去问快递的。</p><p>她说，你人挺傻的，但是你会问。</p><p>第一天我去驿站，站在柜台前面，把手机里那张单子摊开给小伙子看。</p><p>我问他，这个怎么填。</p><p>他抬头看我，问，你寄哪儿。</p><p>我说，六个地方。</p><p>他说，六个地方你一张一张填。</p><p>我说，要多少钱。</p><p>他说，你先称。</p><p>我把那六个袋子一个一个放上去。最小的那个是一枚徽章，称出来0.02，他说不足一公斤按一公斤。</p><p>那天我在驿站柜台前面站着算了很久。</p><p>算完我发现一件事：寄六个地方，比我垫给她的钱还多。</p><p>我回去跟她说了。</p><p>她说，那你怎么不问我借钱。</p><p>我说，我借你。</p><p>她说，你哪来的钱。</p><p>我说，我这个月的。</p><p>她说，你一个月多少。</p><p>我说，够。</p><p>她没接这句。</p><p>过了一会儿她发了一句：你不用垫。</p><p>我说，我已经垫了。</p><p>她说，那你把单号给我，我转给她们，让她们直接对。</p><p>我说，好。</p><p>她说，你这个人，钱不是这么花的。</p><p>我说，那钱是怎么花的。</p><p>她说，你现在这样，以后人家不欠你，你也不欠人家，你什么都没了。</p><p>我看到这一句，停了一下。</p><p>因为她说的不是钱。</p><p>她说的是：你这样，你会欠上一个你谁都收不回来的人。</p><p>我没答这一句。</p><p>我把六个单号排好，一张一张拍给她。</p><p>拍了六张。</p><p>第七张我发的是：都发了。</p><p>她说，你怎么知道都发了。</p><p>我说，我数了两遍。</p><p>她说，你数那个干什么。</p><p>我说，万一少一个，你又要去跟人对账。</p><p>她隔了很久才回。</p><p>久到我以为她去上课了。</p><p>然后她说：你还挺会心疼人的。</p><p>发完这一条她立刻又来了一条。</p><p>她说：这话别当回事，我最近说话不过脑子。</p><p>我说，嗯。</p><p>她说，你嗯什么。</p><p>我说，我不过脑子也没关系。</p><p>她说，你讲话真的很烦。</p><p>那段时间我每天下午去一趟驿站。</p><p>她那边晚上十一点以后才有空，她就在那时候核对：几号到了，谁收到没，谁没回话。</p><p>我成了一个不需要她开口的部分。</p><p>我做的事很具体。</p><p>我买袋子，一种是大号的自封袋，一种是气泡膜。我把徽章一枚一枚垫上纸，把立牌一张一张对齐，把色纸的边按平。</p><p>我把每一单的东西在桌上摆成一排，拍照，发给她。</p><p>她有一回回我说，你拍这个干什么。</p><p>我说，你说错了，我这儿有原图。</p><p>她说，我没说错。</p><p>我说，那你回我一句干什么。</p><p>她说，因为你拍得像我妈在家庭群里发的菜。</p><p>我说，那挺好的。</p><p>她说，一点都不好。</p><p>她给的那六个人里，有一个不肯退。</p><p>那个人收了东西，又跟她说她不要了，要她把钱全退。</p><p>她跟我说这个的时候，正好是晚上十一点。</p><p>她说，你去跟她说。</p><p>我说，我说什么。</p><p>她说，我说一句你跟一句。</p><p>于是那天晚上她在我这边坐了一个钟头，把话一句一句喂给我。</p><p>她发一句，我抄一句。</p><p>她发：你好，这批东西我们当时是这么约的。</p><p>我发：你好，这批东西我们当时是这么约的。</p><p>她发：你现在要全退，等于我垫的那部分白垫。</p><p>我发出去。</p><p>她发：你把图给我看一下。</p><p>我发出去。</p><p>对面回了一张图。</p><p>她那边隔了半分钟，发过来一句：这张图是旧的。</p><p>她说，你问她拍摄时间。</p><p>我说，我不会问。</p><p>她说，你就问：这张图是什么时候拍的。</p><p>我发了。</p><p>对面不说话了。</p><p>那一个钟头里，我像一个人形发射器。</p><p>但是那一个钟头也是那一年里我们两个最长的一次连续对话。</p><p>以前我们是十九分钟。</p><p>那天是一个钟头十四分钟。</p><p>我那天晚上把东西收拾完，坐在楼梯口想：原来我们要吵一次别人的架，才能多拿一个钟头。</p><p>第二天我跟她说这句话。</p><p>她说，你别这么算。</p><p>我说，我就算了一次。</p><p>她说，你算这个，说明你还是没明白。</p><p>我说，我明白什么。</p><p>她说，我今天能跟你吵一个钟头，是因为这一小时不用谈我们。</p><p>那晚我拿本子记下她这句话。</p><p>记完我在下面写：原来不说话的那部分，才是我们要命的地方。</p><p>有一件事我没跟她说。</p><p>快递单上有一个&quot;寄件人&quot;栏，还有一栏是&quot;寄件人地址&quot;。</p><p>她的地址我不能写。她那时候的身份，写在我家的地址上，会被我妈看见。</p><p>所以六个包裹的寄件人，我写的是我自己。</p><p>地址是我家的。</p><p>名字我写的不是我的名字。</p><p>我写的是&quot;闻&quot;。</p><p>我这么写是因为我妈每次拿快递都会念单子上的名字。她念&quot;闻&quot;，她只会以为是我一个同学。</p><p>果然，第七个包裹到我家那天，我妈拿着单子进屋，问我，这个谁的。</p><p>我说，我的。</p><p>她说，你叫闻什么。</p><p>我说，就一个姓。</p><p>她说，你这孩子。</p><p>她说，你现在寄东西都不写全名了。</p><p>我说，写全名容易丢。</p><p>我妈把单子放下，走了。</p><p>走到门口她回了一句。</p><p>她说，你寄的东西，最近挺多啊。</p><p>我说，帮同学。</p><p>她说，哪个同学。</p><p>我说，就那个。</p><p>我妈没再问。</p><p>我妈这个人很厉害，她问问题只问到你能答的那一层就停。她知道再往下我就不答了，她也不想听我不答的样子。</p><p>那天晚上我把这件事跟她说了。</p><p>我说，我妈问我是哪个同学。</p><p>她说，你怎么说的。</p><p>我说，我说就那个。</p><p>她笑了。</p><p>她发了一个很长的一段话，中间有两处语法是错的，我看得出她是笑着打的。</p><p>她说，你这个说话方式，跟你那个搪瓷杯一样。</p><p>我说，杯子怎么了。</p><p>她说，杯子是把口磨平了让人不敢用。</p><p>她说，你妈那个问句，是被你磨平了。</p><p>那天夜里我躺在床上看天花板。</p><p>我想，我在这段关系里，第一次有了一件具体的事做。</p><p>以前我做的事都是虚的：我等，我数，我抄，我删。</p><p>现在我会打包。我会填单。我知道哪个驿站周五下午人少，不用排队。我知道气泡膜要缠两圈，缠一圈徽章的别针会把膜顶破。</p><p>我知道这些是因为我要让她少跟人对一次账。</p><p>我也知道另一件事。</p><p>她给我的这些活，一件一件做完以后，我手上什么都不会剩下。</p><p>没有一个字，没有一张纸。</p><p>只有一个快递单号查不到的、已经签收的记录。</p>',152)])])}const m=t(o,[["render",r]]);export{l as __pageData,m as default};
